-- Verify BEFORE renaming anything.  Row count plus a checksum over the key,
-- so a partial or misaligned load is caught rather than silently swapped in.
DECLARE @src_rows bigint, @dst_rows bigint;
DECLARE @src_sum decimal(38,0), @dst_sum decimal(38,0);

SELECT @src_rows = COUNT_BIG(*), @src_sum = SUM(CAST([spectrum_pk] AS decimal(38,0)))
FROM dbo.apogee_net_apogee_star;
SELECT @dst_rows = COUNT_BIG(*), @dst_sum = SUM(CAST([spectrum_pk] AS decimal(38,0)))
FROM dbo.apogee_net_apogee_star_move;

IF @src_rows <> @dst_rows OR ISNULL(@src_sum, -1) <> ISNULL(@dst_sum, -1)
BEGIN
    RAISERROR('VERIFY FAILED for apogee_net_apogee_star: source %I64d rows / dest %I64d rows. Staging table dbo.apogee_net_apogee_star_move left in place, nothing renamed.',
              16, 1, @src_rows, @dst_rows);
    SET NOEXEC ON;
END
ELSE
    PRINT '  verified: ' + CAST(@dst_rows AS varchar(20)) + ' rows, checksum matches';
GO

-- Swap.  The original is RENAMED, not dropped - drop dbo.apogee_net_apogee_star_old by hand once
-- you are satisfied.  Until then PRIMARY still holds the old heap.
EXEC sp_rename 'dbo.apogee_net_apogee_star', 'apogee_net_apogee_star_old';
GO
EXEC sp_rename 'dbo.apogee_net_apogee_star_move', 'apogee_net_apogee_star';
GO

PRINT '  done - dbo.apogee_net_apogee_star now on [SPEC]; original kept as dbo.apogee_net_apogee_star_old';
GO


